// The bridge between the Svelte application and the bound Go struct.
//
// The functions are the wrappers generated by Wails v2 from the exported
// methods of ui.App. The application never imports the Go packages and
// never duplicates their types: the types come from the generated
// wailsjs/go/models module.
//
// The generated directory is written by the Wails binding generator:
//
//   go run -tags "ui bindings" ./cmd/codixai ui --root .

import {
  Audit,
  AuditAsync,
  CancelAudit,
  ChooseFile,
  ChooseRepository,
  Export,
  Root,
  Verify,
  VerifyAsync,
} from './wailsjs/go/ui/App'
import { EventsOn } from './wailsjs/runtime/runtime'
import type { ui } from './wailsjs/go/models'

export {
  Audit,
  AuditAsync,
  CancelAudit,
  ChooseFile,
  ChooseRepository,
  Export,
  Root,
  Verify,
  VerifyAsync,
}

// isBridgeAvailable reports whether the window runtime injected the
// bindings. A plain browser (the Vite dev server without Wails) has no
// window.go, and the screen explains how to start the interface instead of
// failing on the first call.
export function isBridgeAvailable(): boolean {
  if (typeof window === 'undefined') {
    return false
  }
  const candidate = window as unknown as {
    go?: { ui?: { App?: Record<string, unknown> } }
  }
  return Boolean(candidate.go?.ui?.App)
}

// onAuditEvent subscribes to the events of the asynchronous audit.
export function onAuditEvent(
  handler: (event: ui.AuditEvent) => void,
): () => void {
  return EventsOn('audit:event', handler)
}

// onVerifyEvent subscribes to the events of the asynchronous verification.
export function onVerifyEvent(
  handler: (event: ui.VerifyEvent) => void,
): () => void {
  return EventsOn('verify:event', handler)
}
